def find_topmost_carpet(n, carpets, point) -> int:
    x, y = point
    # Iterate from topmost (last) to bottom
    for idx in range(n - 1, -1, -1):
        a, b, g, k = carpets[idx]
        if a <= x <= a + g and b <= y <= b + k:
            return idx + 1  # 1-based index
    return -1

def max_value_on_paths(N: int, grid_values: list) -> int:
    # Build grid with 1-indexed coordinates
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, v in grid_values:
        if x == 0 and y == 0 and v == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            grid[x][y] = v

    # Edge case: single cell
    if N == 1:
        return grid[1][1]

    # Initialize DP arrays
    NEG = -10**9
    dp_prev = [[NEG] * (N + 1) for _ in range(N + 1)]
    dp_prev[1][1] = grid[1][1]

    # Iterate over steps t = x1 + y1 = x2 + y2
    for t in range(3, 2 * N + 1):
        dp_cur = [[NEG] * (N + 1) for _ in range(N + 1)]
        # x1 ranges
        x1_min = max(1, t - N)
        x1_max = min(N, t - 1)
        for x1 in range(x1_min, x1_max + 1):
            y1 = t - x1
            if y1 < 1 or y1 > N:
                continue
            for x2 in range(x1_min, x1_max + 1):
                y2 = t - x2
                if y2 < 1 or y2 > N:
                    continue
                best = NEG
                # transitions: each path can come from up or left
                for dx1 in (0, 1):
                    for dx2 in (0, 1):
                        prev_x1 = x1 - dx1
                        prev_y1 = y1 - (1 - dx1)
                        prev_x2 = x2 - dx2
                        prev_y2 = y2 - (1 - dx2)
                        if prev_x1 < 1 or prev_y1 < 1 or prev_x2 < 1 or prev_y2 < 1:
                            continue
                        val = dp_prev[prev_x1][prev_x2]
                        if val > best:
                            best = val
                if best == NEG:
                    continue
                add = grid[x1][y1]
                if x1 != x2 or y1 != y2:
                    add += grid[x2][y2]
                dp_cur[x1][x2] = best + add
        dp_prev = dp_cur

    return dp_prev[N][N] if dp_prev[N][N] != NEG else 0

def find_number_combinations():
    combos = []
    for a in range(123, 988):
        s_a = str(a)
        if '0' in s_a or len(set(s_a)) != 3:
            continue
        b = a * 2
        c = a * 3
        if b > 999 or c > 999:
            continue
        s_b = str(b)
        s_c = str(c)
        if '0' in s_b or '0' in s_c:
            continue
        if len(set(s_b)) != 3 or len(set(s_c)) != 3:
            continue
        all_digits = s_a + s_b + s_c
        if len(set(all_digits)) == 9 and set(all_digits) == set('123456789'):
            combos.append((a, b, c))
    combos.sort(key=lambda x: x[0])
    return combos

def calculate_scholarship(grades: List[int], leader: str, west: str, papers: int) -> int:
    avg, class_eval = grades
    scholarship = 0
    if avg > 80 and papers >= 1:
        scholarship += 8000
    if avg > 85 and class_eval > 80:
        scholarship += 4000
    if avg > 90:
        scholarship += 2000
    if avg > 85 and west == 'Y':
        scholarship += 1000
