def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    first = True
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue
        # Determine sign
        if first:
            sign = '-' if coeff < 0 else ''
        else:
            sign = '-' if coeff < 0 else '+'
        # Absolute coefficient
        abs_coeff = abs(coeff)
        # Coefficient part
        if abs_coeff == 1 and degree > 0:
            coeff_part = ''
        else:
            coeff_part = str(abs_coeff)
        # Variable part
        if degree > 1:
            var_part = f'x^{degree}'
        elif degree == 1:
            var_part = 'x'
        else:
            var_part = ''
        term = f"{sign}{coeff_part}{var_part}"
        terms.append(term)
        first = False
    if not terms:
        return '0'
    return ''.join(terms)

def select_volunteers(n: int, m: int, applicants: list) -> tuple:
    # Sort applicants by score descending, then registration number ascending
    sorted_applicants = sorted(applicants, key=lambda x: (-x[1], x[0]))
    # Calculate cutoff index (150% of planned recruits, rounded down)
    cutoff_index = int(1.5 * m)
    if not sorted_applicants:
        return (0, [])
    # Determine cutoff score
    if cutoff_index <= 0:
        cutoff_score = sorted_applicants[0][1]
    elif cutoff_index > len(sorted_applicants):
        cutoff_score = sorted_applicants[-1][1]
    else:
        cutoff_score = sorted_applicants[cutoff_index - 1][1]
    # Filter qualified applicants
    qualified = [app for app in sorted_applicants if app[1] >= cutoff_score]
    return (cutoff_score, qualified)

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"
    mapping = {}
    rev_mapping = {}
    for e, o in zip(encoded, original):
        if e in mapping:
            if mapping[e] != o:
                return "Failed"
        else:
            if o in rev_mapping and rev_mapping[o] != e:
                return "Failed"
            mapping[e] = o
            rev_mapping[o] = e
    if len(mapping) != 26 or len(rev_mapping) != 26:
        return "Failed"
    decoded_chars = []
    for ch in message:
        if ch not in mapping:
            return "Failed"
        decoded_chars.append(mapping[ch])
    return "".join(decoded_chars)

def count_partitions(n: int, k: int, x: int) -> int:
    if k == 0:
        return 1 if n == 0 else 0
    if n < k * x:
        return 0
    m = n - k * x
    # dp[i][j] = number of partitions of i into parts of size at most j
    dp = [[0] * (k + 1) for _ in range(m + 1)]
    for j in range(k + 1):
        dp[0][j] = 1
    for i in range(1, m + 1):
        for j in range(1, k + 1):
            dp[i][j] = dp[i][j - 1]
            if i >= j:
                dp[i][j] += dp[i - j][j]
    return dp[m][k]

def count_coprime_pairs(x0: int, y0: int) -> int:
    def _gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    if y0 % x0 != 0:
        return 0
    n = y0 // x0
    count = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            a = i
            b = n // i
            if _gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
        i += 1
    return count

def preorder_traversal(inorder: str, postorder: str) -> str:
    if not inorder:
        return ''
    root = postorder[-1]
    idx = inorder.index(root)
    left_inorder = inorder[:idx]
    right_inorder = inorder[idx+1:]
    left_postorder = postorder[:len(left_inorder)]
    right_postorder = postorder[len(left_inorder):-1]
    return root + preorder_traversal(left_inorder, left_postorder) + preorder_traversal(right_inorder, right_postorder)

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    if A == B:
        return 0
    from collections import deque
    queue = deque()
    queue.append((A, 0))
    visited = {A}
    max_steps = 10
    while queue:
        current, steps = queue.popleft()
        if steps >= max_steps:
            continue
        for src, tgt in rules:
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_str = current[:idx] + tgt + current[idx + len(src):]
                if new_str == B:
                    return steps + 1
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, steps + 1))
                start = idx + 1
    return "NO ANSWER!"

def generate_numbers(n, rules) -> int:
    from collections import deque
    # Map each digit to a list of possible replacements
    rule_map = {}
    for x, y in rules:
        rule_map.setdefault(str(x), []).append(str(y))
    visited = set([n])
    queue = deque([n])
    while queue:
        num = queue.popleft()
        s = str(num)
        for i, ch in enumerate(s):
            if ch in rule_map:
                for y in rule_map[ch]:
                    new_s = s[:i] + y + s[i+1:]
                    new_num = int(new_s)
                    if new_num not in visited:
                        visited.add(new_num)
                        queue.append(new_num)
    return len(visited)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    # Helper to determine truth of a single statement
    def is_truthful(speaker: str, stmt: str) -> bool:
        # Remove trailing period and strip whitespace
        stmt_clean = stmt.strip().rstrip('.')
        # Ignore statements about days of the week
        lower_stmt = stmt_clean.lower()
        for day in days_of_week:
            if day.lower() in lower_stmt:
                return None  # ignore this statement
        parts = stmt_clean.split()
        if not parts:
            return None
        # Handle "I am guilty" or "I am not guilty"
        if parts[0] == "I":
            if len(parts) == 3 and parts[1] == "am" and parts[2] == "guilty":
                return scenario == speaker
            if len(parts) == 4 and parts[1] == "am" and parts[2] == "not" and parts[3] == "guilty":
                return scenario != speaker
            return None
        # Handle "<NAME> is guilty" or "<NAME> is not guilty"
        if len(parts) >= 3 and parts[1] == "is":
            target = parts[0]
            if len(parts) == 3 and parts[2] == "guilty":
                return scenario == target
            if len(parts) == 4 and parts[2] == "not" and parts[3] == "guilty":
                return scenario != target
            return None
        return None

    for speaker, stmts in statements.items():
        for stmt in stmts:
            truth = is_truthful(speaker, stmt)
            if truth is None:
                continue  # ignored statement
            if speaker in liar_count:
                if truth:
                    return False  # liar said a true statement
            else:
                if not truth:
                    return False  # truth-teller said a false statement
    return True

